//! .NET-compatible persisted UTC timestamps, without a calendar dependency.
use anyhow::{Result,ensure};
use windows_sys::Win32::{Foundation::{FILETIME,SYSTEMTIME},System::Time::{FileTimeToSystemTime,SystemTimeToFileTime,TzSpecificLocalTimeToSystemTime}};
const EPOCH:u64=116_444_736_000_000_000;
pub(crate) fn now_ms()->u64{std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_millis()as u64}
pub(crate) fn iso(ms:u64)->Result<String>{let raw=ms.checked_mul(10_000).and_then(|v|v.checked_add(EPOCH)).ok_or_else(||anyhow::anyhow!("Timestamp overflow"))?;let file=FILETIME{dwLowDateTime:raw as u32,dwHighDateTime:(raw>>32)as u32};let mut value:SYSTEMTIME=unsafe{std::mem::zeroed()};ensure!(unsafe{FileTimeToSystemTime(&file,&mut value)}!=0,"Invalid timestamp");Ok(format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}.{:03}Z",value.wYear,value.wMonth,value.wDay,value.wHour,value.wMinute,value.wSecond,value.wMilliseconds))}
pub(crate) fn parse(text:&str)->Option<u64>{
    if text.len()<19||!text.is_ascii()||&text[4..5]!="-"||&text[7..8]!="-"||!matches!(&text[10..11],"T"|" ")||&text[13..14]!=":"||&text[16..17]!=":"{return None;}
    let num=|start,end|text.get(start..end)?.parse::<u16>().ok();let mut value=SYSTEMTIME{wYear:num(0,4)?,wMonth:num(5,7)?,wDayOfWeek:0,wDay:num(8,10)?,wHour:num(11,13)?,wMinute:num(14,16)?,wSecond:num(17,19)?,wMilliseconds:0};let mut rest=&text[19..];
    if let Some(fraction)=rest.strip_prefix('.') {let count=fraction.bytes().take_while(u8::is_ascii_digit).count();if count==0||count>7{return None;}let digits=&fraction[..count.min(3)];value.wMilliseconds=digits.parse::<u16>().ok()?*10u16.pow((3-digits.len())as u32);rest=&fraction[count..];}
    let offset=if rest=="Z"{0i64}else if rest.is_empty(){let mut utc=unsafe{std::mem::zeroed()};if unsafe{TzSpecificLocalTimeToSystemTime(std::ptr::null(),&value,&mut utc)}==0{return None;}value=utc;0}else if rest.len()==6&&matches!(&rest[..1],"+"|"-")&&&rest[3..4]==":"{let hour=rest[1..3].parse::<i64>().ok()?;let minute=rest[4..].parse::<i64>().ok()?;if hour>14||minute>59||(hour==14&&minute!=0){return None;}(hour*60+minute)*60_000*if rest.starts_with('+'){1}else{-1}}else{return None;};
    let mut file=FILETIME{dwLowDateTime:0,dwHighDateTime:0};if unsafe{SystemTimeToFileTime(&value,&mut file)}==0{return None;}let raw=((file.dwHighDateTime as u64)<<32)|file.dwLowDateTime as u64;let ms=i64::try_from(raw.checked_sub(EPOCH)?/10_000).ok()?.checked_sub(offset)?;u64::try_from(ms).ok()
}
#[cfg(test)]mod tests{use super::*;#[test]fn persisted_dotnet_fraction_and_offset_roundtrip(){let ms=parse("2026-11-03T08:01:02.1234567+08:00").unwrap();assert_eq!(iso(ms).unwrap(),"2026-11-03T00:01:02.123Z");assert_eq!(parse("2026-11-03T00:01:02Z"),parse("2026-11-03T00:01:02.000Z"));}#[test]fn malformed_dates_and_offsets_are_unknown(){for value in["2026-13-33T00:00:00Z","2026-11-03T00:00:00+15:00","bad","2026-11-03T00:00:00oops"]{assert!(parse(value).is_none(),"{value}");}}}
